_WORD_PATTERN = re.compile(r"\b(" + '|'.join(sorted(map(re.escape, _WORDS), key=len, reverse=True)) + r")\b")

def configured_language() -> str:
    return 'fr'

def tr(text: str) -> str:
    """Keep source strings intact until UI text has a reviewed catalogue."""
    return text

def trf(template: str, *values: object) -> str:
    """Translate only literal parts of a formatted interface message."""
    translated = tr(template)
    for index, value in enumerate(values):
        translated = translated.replace(f'\x1f{index}\x1f', str(value))
    return translated

